for serial, rec, desc, silver, payor in data:
    if serial:
        fn = f"draft_#{serial}.json"
    else:
        # 用名称做文件名避免碰撞（serial 为空）
        fn = f"draft_#EMPTY_{hash(desc)%100000}.json"
    obj = {
        "serial": serial,
        "recommend": rec,
        "desc_cn": desc,
        "silver_reason": silver,
        "payor_model": payor,
    }
    with open(os.path.join(OUT, fn), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    print("wrote", fn)
print("TOTAL", len(data))
